      content: '<div class="not-content my-6">\n  <CalendarPreview client:load />\n</div>\n\n\n## Contract\n\n<div class="not-content">\n  <SpecRenderer client:load component="calendar" />\n</div>\n\n## Installation\n\n<PackageInstall />\n\n## Usage\n\n```tsx\n<Calendar value={selectedDate} onChange={setSelectedDate} />\n\n<Calendar\n  mode="range"\n  rangeStart={startDate}\n  rangeEnd={endDate}\n  onRangeChange={(start, end) => {\n    setStartDate(start);\n    setEndDate(end);\n  }}\n/>\n\n<Calendar weekStartsOn={1} defaultMonth={new Date(2024, 0)} />\n```\n\n## API Reference\n\n<div class="not-content">\n  <PropSpec\n    client:load\n    rows={[\n    { prop: "mode", default: "\\"single\\"", type: "\\"single\\" | \\"range\\"", description: "Selection mode." },\n    { prop: "value", default: "\u2014", type: "Date", description: "Controlled selected date (single mode)." },\n    { prop: "onChange", default: "\u2014", type: "(date: Date) => void", description: "Event handler when date changes (single mode)." },\n    { prop: "rangeStart", default: "\u2014", type: "Date", description: "Controlled range start date (range mode)." },\n    { prop: "rangeEnd", default: "\u2014", type: "Date", description: "Controlled range end date (range mode)." },\n    { prop: "onRangeChange", default: "\u2014", type: "(start?: Date, end?: Date) => void", description: "Event handler when range changes (range mode)." },\n    { prop: "weekStartsOn", default: "0", type: "0 | 1", description: "First day of week: 0 (Sunday) or 1 (Monday)." },\n    { prop: "defaultMonth", default: "\u2014", type: "Date", description: "Initially displayed month." }\n    ]}\n  />\n</div>',
      searchText: 'calendar date picker calendar grid component. <div class="not-content my-6">\n  <calendarpreview client:load />\n</div>\n\n\n## contract\n\n<div class="not-content">\n  <specrenderer client:load component="calendar" />\n</div>\n\n## installation\n\n<packageinstall />\n\n## usage\n\n```tsx\n<calendar value={selecteddate} onchange={setselecteddate} />\n\n<calendar\n  mode="range"\n  rangestart={startdate}\n  rangeend={enddate}\n  onrangechange={(start, end) => {\n    setstartdate(start);\n    setenddate(end);\n  }}\n/>\n\n<calendar weekstartson={1} defaultmonth={new date(2024, 0)} />\n```\n\n## api reference\n\n<div class="not-content">\n  <propspec\n    client:load\n    rows={[\n    { prop: "mode", default: "\\"single\\"", type: "\\"single\\" | \\"range\\"", description: "selection mode." },\n    { prop: "value", default: "\u2014", type: "date", description: "controlled selected date (single mode)." },\n    { prop: "onchange", default: "\u2014", type: "(date: date) => void", description: "event handler when date changes (single mode)." },\n    { prop: "rangestart", default: "\u2014", type: "date", description: "controlled range start date (range mode)." },\n    { prop: "rangeend", default: "\u2014", type: "date", description: "controlled range end date (range mode)." },\n    { prop: "onrangechange", default: "\u2014", type: "(start?: date, end?: date) => void", description: "event handler when range changes (range mode)." },\n    { prop: "weekstartson", default: "0", type: "0 | 1", description: "first day of week: 0 (sunday) or 1 (monday)." },\n    { prop: "defaultmonth", default: "\u2014", type: "date", description: "initially displayed month." }\n    ]}\n  />\n</div>\n'
