      title: "Resizable",
      description: "Split panel layout with drag handles.",
      category: "components",
      content: '<div class="not-content my-6">\n  <ResizableDemo client:load />\n</div>\n\n\n## Contract\n\n<div class="not-content">\n  <SpecRenderer client:load component="resizable" />\n</div>\n\n## Installation\n\n<PackageInstall />\n\n## Usage\n\n```tsx\n<ResizablePanelGroup orientation="horizontal">\n  <ResizablePanel defaultSize={50} minSize={30}>\n    Left panel\n  </ResizablePanel>\n  <ResizableHandle />\n  <ResizablePanel defaultSize={50} minSize={30}>\n    Right panel\n  </ResizablePanel>\n</ResizablePanelGroup>\n\n<ResizablePanelGroup orientation="vertical" onLayout={(sizes) => console.log(sizes)}>\n  <ResizablePanel size={topPanelSize} onResize={setTopPanelSize}>\n    Top\n  </ResizablePanel>\n  <ResizableHandle withHandle />\n  <ResizablePanel>\n    Bottom\n  </ResizablePanel>\n</ResizablePanelGroup>\n```\n\n## API Reference\n\n### ResizablePanelGroup\n\n<div class="not-content">\n  <PropSpec\n    client:load\n    rows={[\n    { prop: "orientation", default: "\\"horizontal\\"", type: "\\"horizontal\\" | \\"vertical\\"", description: "Split direction." },\n    { prop: "onLayout", default: "\u2014", type: "(sizes: number[]) => void", description: "Fires after resize with panel sizes (percentages summing to ~100)." }\n    ]}\n  />\n</div>\n### ResizablePanel\n\n<div class="not-content">\n  <PropSpec\n    client:load\n    rows={[\n    { prop: "defaultSize", default: "50", type: "number", description: "Initial size as percentage." },\n    { prop: "minSize", default: "10", type: "number", description: "Minimum size percentage." },\n    { prop: "maxSize", default: "100", type: "number", description: "Maximum size percentage." },\n    { prop: "size", default: "\u2014", type: "number", description: "Controlled size percentage." },\n    { prop: "onResize", default: "\u2014", type: "(size: number) => void", description: "Event handler when panel resizes." }\n    ]}\n  />\n</div>\n### ResizableHandle\n\n<div class="not-content">\n  <PropSpec\n    client:load\n    rows={[\n    { prop: "withHandle", default: "false", type: "boolean", description: "Shows grip affordance on separator." },\n    { prop: "disabled", default: "false", type: "boolean", description: "Disables resizing." }\n    ]}\n  />\n</div>',
      searchText: 'resizable split panel layout with drag handles. <div class="not-content my-6">\n  <resizabledemo client:load />\n</div>\n\n\n## contract\n\n<div class="not-content">\n  <specrenderer client:load component="resizable" />\n</div>\n\n## installation\n\n<packageinstall />\n\n## usage\n\n```tsx\n<resizablepanelgroup orientation="horizontal">\n  <resizablepanel defaultsize={50} minsize={30}>\n    left panel\n  </resizablepanel>\n  <resizablehandle />\n  <resizablepanel defaultsize={50} minsize={30}>\n    right panel\n  </resizablepanel>\n</resizablepanelgroup>\n\n<resizablepanelgroup orientation="vertical" onlayout={(sizes) => console.log(sizes)}>\n  <resizablepanel size={toppanelsize} onresize={settoppanelsize}>\n    top\n  </resizablepanel>\n  <resizablehandle withhandle />\n  <resizablepanel>\n    bottom\n  </resizablepanel>\n</resizablepanelgroup>\n```\n\n## api reference\n\n### resizablepanelgroup\n\n<div class="not-content">\n  <propspec\n    client:load\n    rows={[\n    { prop: "orientation", default: "\\"horizontal\\"", type: "\\"horizontal\\" | \\"vertical\\"", description: "split direction." },\n    { prop: "onlayout", default: "\u2014", type: "(sizes: number[]) => void", description: "fires after resize with panel sizes (percentages summing to ~100)." }\n    ]}\n  />\n</div>\n### resizablepanel\n\n<div class="not-content">\n  <propspec\n    client:load\n    rows={[\n    { prop: "defaultsize", default: "50", type: "number", description: "initial size as percentage." },\n    { prop: "minsize", default: "10", type: "number", description: "minimum size percentage." },\n    { prop: "maxsize", default: "100", type: "number", description: "maximum size percentage." },\n    { prop: "size", default: "\u2014", type: "number", description: "controlled size percentage." },\n    { prop: "onresize", default: "\u2014", type: "(size: number) => void", description: "event handler when panel resizes." }\n    ]}\n  />\n</div>\n### resizablehandle\n\n<div class="not-content">\n  <propspec\n    client:load\n    rows={[\n    { prop: "withhandle", default: "false", type: "boolean", description: "shows grip affordance on separator." },\n    { prop: "disabled", default: "false", type: "boolean", description: "disables resizing." }\n    ]}\n  />\n</div>\n'
