      href: "/ko/components/tooltip/",
      title: "Tooltip",
      description: "\uD638\uBC84 \uB610\uB294 \uD3EC\uCEE4\uC2A4 \uC2DC \uC0C1\uD669\uBCC4 \uD14D\uC2A4\uD2B8 \uD31D\uC5C5.",
      category: "guides",
      content: '<div class="not-content my-6">\n  <TooltipDemo client:load />\n</div>\n\n\n## \uACC4\uC57D\n\n<div class="not-content">\n  <SpecRenderer client:load component="tooltip" />\n</div>\n\n## \uC124\uCE58\n\n<PackageInstall />\n\n## \uC0AC\uC6A9\uBC95\n\n```tsx\n<Tooltip trigger={<Button>Hover me</Button>} content="Helpful tooltip text" />\n\n<Tooltip\n  trigger={<IconButton icon="info" />}\n  content="Extended information"\n  position="Top"\n  align="Center"\n/>\n```\n\n## API \uB808\uD37C\uB7F0\uC2A4\n\n<div class="not-content">\n  <PropSpec\n    client:load\n    rows={[\n    { prop: "trigger", default: "\u2014", type: "ReactNode", description: "\uD234\uD301\uC744 \uD2B8\uB9AC\uAC70\uD558\uB294 \uC694\uC18C(\uD544\uC218)." },\n    { prop: "content", default: "\u2014", type: "ReactNode", description: "\uD234\uD301 \uCF58\uD150\uCE20(\uD544\uC218)." },\n    { prop: "position", default: "\\"Top\\"", type: "\\"Top\\" | \\"Left\\" | \\"Bottom\\" | \\"Right\\"", description: "\uD2B8\uB9AC\uAC70 \uAE30\uC900 \uC704\uCE58." },\n    { prop: "align", default: "\\"Center\\"", type: "\\"Start\\" | \\"Center\\" | \\"End\\"", description: "\uAC00\uC7A5\uC790\uB9AC \uAE30\uC900 \uC815\uB82C." },\n    { prop: "delayMs", default: "700", type: "number", description: "\uD45C\uC2DC \uC804 \uC9C0\uC5F0(\uBC00\uB9AC\uCD08)." },\n    { prop: "open", default: "\u2014", type: "boolean", description: "\uC81C\uC5B4\uD615 \uC5F4\uB9BC \uC0C1\uD0DC." },\n    { prop: "defaultOpen", default: "\u2014", type: "boolean", description: "\uBE44\uC81C\uC5B4\uD615 \uCD08\uAE30 \uC5F4\uB9BC \uC0C1\uD0DC." },\n    { prop: "onOpenChange", default: "\u2014", type: "(open: boolean) => void", description: "\uC5F4\uB9BC \uC0C1\uD0DC \uBCC0\uACBD \uC2DC \uC774\uBCA4\uD2B8 \uD578\uB4E4\uB7EC." }\n    ]}\n  />\n</div>',
      searchText: 'tooltip \uD638\uBC84 \uB610\uB294 \uD3EC\uCEE4\uC2A4 \uC2DC \uC0C1\uD669\uBCC4 \uD14D\uC2A4\uD2B8 \uD31D\uC5C5. <div class="not-content my-6">\n  <tooltipdemo client:load />\n</div>\n\n\n## \uACC4\uC57D\n\n<div class="not-content">\n  <specrenderer client:load component="tooltip" />\n</div>\n\n## \uC124\uCE58\n\n<packageinstall />\n\n## \uC0AC\uC6A9\uBC95\n\n```tsx\n<tooltip trigger={<button>hover me</button>} content="helpful tooltip text" />\n\n<tooltip\n  trigger={<iconbutton icon="info" />}\n  content="extended information"\n  position="top"\n  align="center"\n/>\n```\n\n## api \uB808\uD37C\uB7F0\uC2A4\n\n<div class="not-content">\n  <propspec\n    client:load\n    rows={[\n    { prop: "trigger", default: "\u2014", type: "reactnode", description: "\uD234\uD301\uC744 \uD2B8\uB9AC\uAC70\uD558\uB294 \uC694\uC18C(\uD544\uC218)." },\n    { prop: "content", default: "\u2014", type: "reactnode", description: "\uD234\uD301 \uCF58\uD150\uCE20(\uD544\uC218)." },\n    { prop: "position", default: "\\"top\\"", type: "\\"top\\" | \\"left\\" | \\"bottom\\" | \\"right\\"", description: "\uD2B8\uB9AC\uAC70 \uAE30\uC900 \uC704\uCE58." },\n    { prop: "align", default: "\\"center\\"", type: "\\"start\\" | \\"center\\" | \\"end\\"", description: "\uAC00\uC7A5\uC790\uB9AC \uAE30\uC900 \uC815\uB82C." },\n    { prop: "delayms", default: "700", type: "number", description: "\uD45C\uC2DC \uC804 \uC9C0\uC5F0(\uBC00\uB9AC\uCD08)." },\n    { prop: "open", default: "\u2014", type: "boolean", description: "\uC81C\uC5B4\uD615 \uC5F4\uB9BC \uC0C1\uD0DC." },\n    { prop: "defaultopen", default: "\u2014", type: "boolean", description: "\uBE44\uC81C\uC5B4\uD615 \uCD08\uAE30 \uC5F4\uB9BC \uC0C1\uD0DC." },\n    { prop: "onopenchange", default: "\u2014", type: "(open: boolean) => void", description: "\uC5F4\uB9BC \uC0C1\uD0DC \uBCC0\uACBD \uC2DC \uC774\uBCA4\uD2B8 \uD578\uB4E4\uB7EC." }\n    ]}\n  />\n</div>\n'
